// Validates and rebuilds the backup configuration from raw form input.
// Nothing here is trusted until it passes its regex - the object returned
// is what every downstream SSH/shell command will interpolate.

const form = $('Backup Configuration Form').item.json;

function fail(field, reason) {
  throw new Error(`Invalid "${field}": ${reason}`);
}

// --- Source directory: absolute path, no shell metacharacters ---
const sourceDirRaw = (form['Source directory on the server'] || '').trim();
const sourceDirPattern = /^\/$|^\/[A-Za-z0-9._-]+(\/[A-Za-z0-9._-]+)*$/;
if (!sourceDirPattern.test(sourceDirRaw)) {
  fail('Source directory on the server', 'must be an absolute path using only letters, numbers, dot, dash, underscore and slash');
}
const sourceDir = sourceDirRaw;

// --- Backup mode: only the two known dropdown labels are ever accepted ---
const modeLabel = form['Backup mode'] || '';
let mode;
if (modeLabel.toLowerCase().includes('sync')) {
  mode = 'sync';
} else if (modeLabel.toLowerCase().includes('versioned')) {
  mode = 'versioned';
} else {
  fail('Backup mode', 'unrecognized option');
}

// --- Bucket name: Backblaze B2 naming rules (6-63 chars, letters/numbers/dashes) ---
const bucketRaw = (form['Backblaze B2 bucket name'] || '').trim();
const bucketPattern = /^[A-Za-z0-9-]{6,63}$/;
if (!bucketPattern.test(bucketRaw)) {
  fail('Backblaze B2 bucket name', 'must be 6-63 characters: letters, numbers and dashes only');
}
const bucket = bucketRaw;

// --- Destination path inside the bucket ---
const destPrefixRaw = (form['Destination path inside the bucket'] || 'backups').trim();
const destPrefixTrimmed = destPrefixRaw.replace(/^\/+|\/+$/g, '') || 'backups';
const destPrefixPattern = /^[A-Za-z0-9._-]+(\/[A-Za-z0-9._-]+)*$/;
if (!destPrefixPattern.test(destPrefixTrimmed)) {
  fail('Destination path inside the bucket', 'only letters, numbers, dot, dash, underscore and slash are allowed');
}
const destPrefix = destPrefixTrimmed;

// --- Backblaze B2 Key ID ---
const b2KeyIdRaw = (form['Backblaze B2 Key ID'] || '').trim();
const b2KeyIdPattern = /^[A-Za-z0-9]{10,64}$/;
if (!b2KeyIdPattern.test(b2KeyIdRaw)) {
  fail('Backblaze B2 Key ID', 'expected an alphanumeric key ID (10-64 chars)');
}
const b2KeyId = b2KeyIdRaw;

// --- Backblaze B2 Application Key ---
const b2AppKeyRaw = (form['Backblaze B2 Application Key'] || '').trim();
const b2AppKeyPattern = /^[A-Za-z0-9+/=_-]{10,128}$/;
if (!b2AppKeyPattern.test(b2AppKeyRaw)) {
  fail('Backblaze B2 Application Key', 'expected an alphanumeric/base64-style key (10-128 chars)');
}
const b2AppKey = b2AppKeyRaw;

// --- Encryption toggle ---
const wantsEncryption = (form['Encrypt the backup?'] || '').trim().toLowerCase() === 'yes';

// --- Passphrase: only required and validated when encryption is enabled ---
let cryptPassphrase = null;
if (wantsEncryption) {
  const passphraseRaw = form['encryption passphrase'] || '';
  // Block characters that can break out of a double-quoted shell string:
  // double quote, backtick, dollar sign, backslash, and any line break.
  const forbidden = /["`$\\\r\n]/;
  if (passphraseRaw.length < 8) {
    fail('encryption passphrase', 'must be at least 8 characters when encryption is enabled');
  }
  if (forbidden.test(passphraseRaw)) {
    fail('encryption passphrase', 'cannot contain ", `, $, \\ or line breaks');
  }
  cryptPassphrase = passphraseRaw;
}

const config = {
  sourceDir,
  mode,
  bucket,
  destPrefix,
  remoteName: 'b2backup',
  encrypted: wantsEncryption,
};

return [{
  json: {
    config,
    b2KeyId,
    b2AppKey,
    cryptPassphrase,
  }
}];
